// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Mikroekonomi: tüketici ve üretici kuramı (kolay).
const ozEconomics6Kolay = <(String, String, List<String>, String)>[
  ('Tüketici kuramında, herhangi iki mal sepeti A ve B için tüketicinin ya A\'yı B\'ye, ya B\'yi A\'ya tercih ettiğini ya da ikisine kayıtsız kaldığını söyleyen varsayım hangisidir?', 'Tamlık', ['Geçişlilik', 'Süreklilik', 'Dışbükeylik'], 'Tamlık varsayımı, tüketicinin her sepet çiftini karşılaştırabildiğini söyler; karar veremediği bir çift yoktur.'),
  ('Bir tüketici çayı kahveye, kahveyi de meyve suyuna tercih ediyor. Tercihleri rasyonelse çay ile meyve suyu arasındaki tercihi ne olmalıdır?', 'Çayı meyve suyuna tercih etmelidir.', ['Meyve suyunu çaya tercih etmelidir.', 'İkisine kayıtsız kalmalıdır.', 'Tercihi belirlenemez; ek bilgi gerekir.'], 'Geçişlilik varsayımına göre A, B\'ye ve B, C\'ye tercih ediliyorsa A da C\'ye tercih edilir.'),
  ('"Daha çok her zaman daha iyidir" biçiminde özetlenen tercih varsayımı kayıtsızlık eğrileri hakkında neyi garanti eder?', 'Eğrilerin negatif eğimli olmasını', ['Eğrilerin orijine göre dışbükey olmasını', 'Eğrilerin doğrusal olmasını', 'Eğrilerin eksenleri kesmesini'], 'Monotonluk (doyumsuzluk) varsayımı altında bir maldan fazla alan tüketicinin aynı faydada kalması için diğer maldan vazgeçmesi gerekir; bu da negatif eğim demektir.'),
  ('Bir tüketici ortalamaları uç sepetlere tercih ediyorsa, yani iki kayıtsız sepetin karışımını en az onlar kadar iyi buluyorsa, bu hangi tercih varsayımıdır?', 'Dışbükeylik', ['Tamlık', 'Yansımalılık', 'Yerel doyumsuzluk'], 'Dışbükey tercihler çeşitliliği sever; kayıtsız iki sepetin ağırlıklı ortalaması en az onlar kadar tercih edilir ve kayıtsızlık eğrileri orijine göre dışbükey olur.'),
  ('Ordinal (sıralı) fayda yaklaşımına göre bir fayda fonksiyonunun verdiği sayılar neyi gösterir?', 'Yalnızca sepetlerin tercih sırasını', ['Tüketicinin hissettiği hazzın ölçülebilir miktarını', 'İki sepet arasındaki tatmin farkının kaç kat olduğunu', 'Malların piyasa fiyatlarını'], 'Ordinal yaklaşımda yalnız sıralama anlamlıdır; 10 faydalı sepetin 5 faydalı sepetten \'iki kat iyi\' olduğu söylenemez.'),
  ('Kardinal fayda yaklaşımını ordinal yaklaşımdan ayıran temel varsayım hangisidir?', 'Faydanın \'util\' gibi bir birimle ölçülebileceği', ['Tüketicinin tercihlerinin eksiksiz ve tutarlı olduğu', 'Tüketicinin bütçe kısıtı altında seçim yaptığı', 'Tüketicinin daha çoğu daha aza tercih ettiği'], 'Kardinal yaklaşım faydanın sayısal olarak ölçülüp karşılaştırılabileceğini varsayar; ordinal yaklaşım yalnız sıralamayı yeterli görür.'),
  ('Bir fayda fonksiyonu U(x,y) = 3x + 3y biçimindeyken bir öğrenci bunu U = x + y olarak yazıyor. Bu sadeleştirme için doğru değerlendirme hangisidir?', 'Tercihleri değiştirmez; aynı sıralamayı verir.', ['Malların marjinal faydaları eşit olduğu için yanlıştır.', 'Kayıtsızlık eğrilerinin eğimini üçte birine indirir.', 'Yalnızca kardinal yaklaşımda geçerlidir.'], 'Pozitif bir sabitle bölmek monoton bir dönüşümdür; sıralama ve kayıtsızlık eğrilerinin eğimi (−1) değişmez.'),
  ('Bir tüketici A sepetini B\'ye tercih ediyor ve B ile C arasında kayıtsız. Tercihleri rasyonelse A ile C arasında ne olmalıdır?', 'A, C\'ye tercih edilir.', ['C, A\'ya tercih edilir.', 'A ile C arasında kayıtsızdır.', 'Karşılaştırma yapılamaz.'], 'Geçişlilik kesin tercih ile kayıtsızlık karışık geldiğinde de geçerlidir: A ≻ B ve B ∼ C ise A ≻ C olur.'),
  ('Aynı kayıtsızlık eğrisi üzerindeki iki sepet için aşağıdakilerden hangisi kesinlikle doğrudur?', 'Tüketiciye aynı fayda düzeyini sağlarlar.', ['Bütçe kısıtı içinde aynı toplam harcamayı gerektirirler.', 'Her iki maldan eşit miktar içerirler.', 'Aynı bütçe doğrusu üzerinde yer alırlar.'], 'Kayıtsızlık eğrisi tanımı gereği eşit fayda veren sepetlerden oluşur; maliyetleri farklı olabilir.'),
  ('Bir tüketici için 1 litre A marka süt ile 1 litre B marka süt arasında hiçbir fark yoksa, bu iki mal için kayıtsızlık eğrileri nasıl bir biçim alır?', 'Eğimi −1 olan düz doğrular', ['L biçimli dik açılı eğriler', 'Orijine göre dışbükey eğriler', 'Yatay doğrular'], 'Tam ikamelerde tüketici iki malı sabit oranda değiştirmeye her zaman razıdır; bire bir ikame eğimi −1 olan doğrular verir.'),
  ('Bir kişi her zaman bir sol ayakkabıyı bir sağ ayakkabıyla birlikte kullanıyor. Bu iki mal için kayıtsızlık eğrileri nasıl görünür?', 'Köşesi 45 derecelik doğru üzerinde olan L biçimli eğriler', ['Negatif eğimli düz doğrular', 'Orijinden çıkan ve pozitif eğimli düz doğrular', 'Dikey doğrular'], 'Tam tamamlayıcılarda fazladan tek bir sol ayakkabı faydayı artırmaz; eğriler köşesi eşit miktarlarda olan dik açılı biçim alır.'),
  ('Bir tüketici sigara dumanından rahatsız oluyor ve dumanlı ortamda kalabilmesi için ek tatlı verilmesini istiyor. Yatay eksende duman, dikey eksende tatlı varken kayıtsızlık eğrileri nasıldır?', 'Pozitif eğimli', ['Negatif eğimli düz doğrular', 'Yatay', 'L biçimli'], 'Duman \'kötü mal\'dır; daha çok duman aynı faydayı korumak için daha çok tatlı gerektirir, bu da eğrileri pozitif eğimli yapar.'),
  ('Bir tüketici X malının miktarını hiç önemsemiyor, yalnızca Y malından fayda alıyor. Yatay eksende X, dikey eksende Y varsa kayıtsızlık eğrileri nasıl olur?', 'Yatay doğrular', ['Dikey doğrular', 'Negatif eğimli doğrular', 'Orijine göre içbükey eğriler'], 'X nötr maldır; X değiştikçe fayda değişmediği için aynı Y miktarı aynı faydayı verir ve eğriler yataydır.'),
  ('Bir tüketicinin en çok tercih ettiği bir \'doygunluk noktası\' (bliss point) varsa, bu noktanın ötesinde ne olur?', 'Daha fazla tüketim faydayı azaltır.', ['Kayıtsızlık eğrileri birbirini kesmeye başlar.', 'Marjinal fayda sonsuza gider.', 'Bütçe doğrusu dikleşir.'], 'Doygunluk noktasından sonra mallar \'kötü\' hâle gelir; ondan uzaklaşmak hangi yönde olursa olsun faydayı düşürür.'),
  ('U = min(x, y) faydasına sahip bir tüketici 10 birim x ve 6 birim y tüketiyor. Bu tüketicinin fayda düzeyi kaçtır?', '6', ['10', '16', '60'], 'Tam tamamlayıcılarda fayda kıt olan malın miktarı ile belirlenir: min(10, 6) = 6. Fazladan 4 birim x hiçbir şey katmaz.'),
  ('U = 2x + y fayda fonksiyonuna sahip bir tüketici için marjinal ikame oranı (yatay eksende x) kaçtır?', '2', ['0,5', '1', 'Tüketim miktarına göre değişir'], 'MRS = MUx/MUy = 2/1 = 2; tüketici bir birim x için iki birim y\'den vazgeçmeye razıdır ve bu oran her noktada sabittir.'),
  ('U = x·y fayda fonksiyonuna sahip bir tüketici 4 birim x ve 12 birim y tüketiyor. Bu noktada marjinal ikame oranı (MUx/MUy) kaçtır?', '3', ['1/3', '48', '4'], 'MUx = y = 12, MUy = x = 4; MRS = 12/4 = 3. Tüketici bir birim x için 3 birim y vermeye razıdır.'),
  ('Azalan marjinal ikame oranı ne anlama gelir?', 'Bir maldan çok tüketildikçe, ondan bir birim daha için diğer maldan vazgeçilmek istenen miktar azalır.', ['Bir maldan çok tüketildikçe hem toplam hem marjinal fayda sürekli azalır.', 'İki malın fiyat oranı zamanla düşer.', 'Gelir arttıkça tüketici daha az mal satın alır.'], 'Kayıtsızlık eğrisi boyunca x arttıkça, ek bir x için feda edilmeye razı olunan y miktarı küçülür; eğri bu yüzden orijine göre dışbükeydir.'),
  ('Tam ikame mallarda marjinal ikame oranının bütün kayıtsızlık eğrisi boyunca aynı kalması neyi gösterir?', 'Tüketicinin iki malı hep aynı oranda değiştirmeye razı olduğunu', ['Tüketicinin iki malı her zaman aynı sabit miktarlarda birlikte kullandığını', 'Malların birinin kötü mal olduğunu', 'Tüketicinin doygunluğa ulaştığını'], 'Sabit MRS, tüketicinin miktarlardan bağımsız olarak hep aynı takas oranını kabul ettiği anlamına gelir.'),
  ('U = 3x + 2y fayda fonksiyonuna sahip bir tüketicinin kayıtsızlık eğrisinin eğimi (yatay eksende x) kaçtır?', '−1,5', ['−2/3', '−1,25', '−2'], 'Eğim = −MUx/MUy = −3/2 = −1,5.'),
  ('Bir kişinin kayıtsızlık haritasında iki farklı eğri aynı noktadan geçerse ne ortaya çıkar?', 'Farklı fayda düzeyleri aynı sepete atanır; bu bir çelişkidir.', ['Malların tam ikame olduğu ve eğimin sabit kaldığı anlaşılır.', 'Kayıtsızlık eğrileri dikleşir.', 'Bütçe doğrusu iki kez kayar.'], 'Bir sepet iki farklı fayda düzeyinde olamaz; kesişme ya monotonluğu ya geçişliliği bozar.'),
  ('Yatay eksende boş zaman, dikey eksende tüketim mallarının gösterildiği bir kayıtsızlık haritasında daha yukarıda ve sağda olan eğriler neyi gösterir?', 'Daha yüksek fayda düzeyini', ['Daha düşük gelir ve daha az tüketim düzeyini', 'Daha fazla çalışma saatini', 'Daha düşük ücret oranını'], 'Her iki mal da \'iyi\' olduğundan iki maldan da daha fazla içeren sepetler daha yüksek faydayı gösterir.'),
  ('Bir mağaza bir malın ilk 10 birimini 5 TL\'den, 10\'u aşan her birimini 3 TL\'den satıyor. Yatay eksende bu mal olduğunda tüketicinin bütçe doğrusu 10. birimden sonra nasıl değişir?', 'Daha yatık hâle gelir.', ['Daha dik hâle gelir.', 'Dikey bir parçaya dönüşür.', 'İçeri doğru paralel kayar.'], 'Kırılma noktasından sonra bu malın göreli fiyatı düştüğü için bütçe doğrusunun eğimi mutlak değerce küçülür, yani doğru yatıklaşır.'),
  ('Devlet şeker satışına kişi başına en çok 5 kilogram sınırı (tayın) koymuştur. Yatay eksende şeker varken tüketicinin bütçe kümesi nasıl değişir?', '5 kilogramda dikey bir sınırla kesilir.', ['Eğimi şekerin fiyatı oranında artarak dikleşir.', 'Dışa doğru paralel kayar.', 'Tamamen ortadan kalkar.'], 'Tayın, bütçe doğrusunun 5 kg\'ın sağındaki kısmını kullanılamaz kılar; küme o noktada dikey bir çizgiyle kesilir.'),
  ('Geliri 600 TL olan bir tüketici için X\'in fiyatı 20 TL, Y\'nin fiyatı 30 TL\'dir. Tüketici gelirinin tamamını X\'e harcarsa kaç birim alabilir?', '30', ['20', '50', '12,5'], '600 / 20 = 30 birim X.'),
  ('Bir tüketiciden tüketimine bakılmaksızın sabit bir tutarda (götürü) vergi alınırsa bütçe doğrusu nasıl etkilenir?', 'İçeri doğru paralel kayar.', ['Eğimi dikleşir.', 'Eğimi dikleşerek X ekseni etrafında döner.', 'Kırık bir doğruya dönüşür.'], 'Götürü vergi geliri azaltır ama göreli fiyatları değiştirmez; bu yüzden eğim korunur ve doğru paralel olarak içe kayar.'),
  ('Gelir sabitken iki malın fiyatı da %25 artarsa bütçe doğrusu nasıl değişir?', 'Eğimi aynı kalarak içe kayar.', ['Eğimi dikleşerek içe döner.', 'Hiç değişmez.', 'Eğimi yatıklaşarak dışa kayar.'], 'Fiyat oranı değişmediği için eğim korunur; ancak reel gelir düştüğü için doğru içe doğru paralel kayar.'),
  ('Tüketici kuramında \'diğer bütün mallar\'ın paraya dönüştürülerek tek bir mal gibi ele alınmasına ne ad verilir?', 'Bileşik mal', ['Kamusal mal', 'Ara mal', 'Bağımsız mal'], 'Hicks\'in bileşik mal kavramıyla, göreli fiyatları değişmeyen bir mal grubu tek bir mal gibi incelenebilir; çoğu zaman \'diğer harcamalara giden para\' olarak gösterilir.'),
  ('Geliri 1.200 TL olan bir tüketici için X\'in fiyatı 40 TL\'den 30 TL\'ye düşüyor. Bütçe doğrusunun X eksenindeki kesişim noktası nasıl değişir?', '30 birimden 40 birime çıkar.', ['40 birimden 30 birime iner.', '30 birimden 36 birime çıkar.', 'Değişmez; çünkü gelir aynı kalmıştır.'], 'Önce 1.200/40 = 30 birim, sonra 1.200/30 = 40 birim alınabilir.'),
  ('Fayda fonksiyonu U = x^0,3 · y^0,7, geliri 1.000 TL ve X\'in fiyatı 10 TL olan bir tüketici dengede kaç birim X satın alır?', '30', ['70', '10', '100'], 'Cobb-Douglas faydada gelirin x\'e giden payı üssüne eşittir: 0,3 × 1.000 = 300 TL; 300 / 10 = 30 birim.'),
  ('Fayda fonksiyonu U = x + y olan bir tüketicinin geliri 100 TL, X\'in fiyatı 4 TL, Y\'nin fiyatı 5 TL\'dir. Tüketici dengede ne satın alır?', '25 birim X, hiç Y', ['20 birim Y, hiç X', 'Her iki maldan 11\'er birim', '12,5 birim X ve 10 birim Y'], 'Tam ikamelerde tüketici birim fayda başına daha ucuz olanı alır; X daha ucuz olduğu için 100/4 = 25 birim X alır.'),
  ('Deniz çay bardağı ile tabağını her zaman birer birer eşleştirerek kullanıyor. Bardak 3 TL, tabak 2 TL ise 100 TL\'lik bütçeyle Deniz kaç bardak alır?', '20', ['25', '33,3', '50'], 'Tam tamamlayıcılarda tüketici eşit sayıda alır: 3x + 2x = 100, yani x = 20 bardak ve 20 tabak.'),
  ('Fayda fonksiyonu U = x·y olan bir tüketicinin geliri 120 TL, X\'in fiyatı 2 TL ve Y\'nin fiyatı 3 TL\'dir. Dengedeki sepet hangisidir?', '30 birim X, 20 birim Y', ['20 birim X, 30 birim Y', '40 birim X ve 13,3 birim Y', '60 birim X, hiç Y'], 'U = xy için gelirin yarısı her mala gider: x = 60/2 = 30, y = 60/3 = 20.'),
  ('Bütün fiyatlar ve gelir aynı oranda, örneğin %40 artarsa rasyonel bir tüketicinin Marshall talebi nasıl değişir?', 'Değişmez.', ['%40 azalır.', '%40 artar.', 'Normal mallarda artar, düşük mallarda azalır.'], 'Marshall talebi fiyatlarda ve gelirde sıfırıncı dereceden homojendir; bütçe kümesi değişmediği için seçim de değişmez.'),
  ('Fiyatlar ve gelir aynı oranda arttığında daha çok tüketmeye başlayan bir kişinin davranışı hangi kavramla açıklanır?', 'Para yanılsaması', ['Kayıptan kaçınma', 'Gösteriş tüketimi', 'Zaman tutarsızlığı'], 'Reel olarak hiçbir şey değişmediği hâlde nominal büyüklüklere tepki vermek para yanılsamasıdır; rasyonel talep kuramı bunu dışlar.'),
  ('Yerel doyumsuzluk altında tüketicinin seçtiği sepetin değeri her zaman gelirine eşit olur. Bu özelliğe tüketici kuramında ne ad verilir?', 'Walras yasası', ['Say yasası', 'Engel yasası', 'Gossen\'in ikinci yasası'], 'Walras yasası, doyumsuz bir tüketicinin bütçesini tam olarak harcadığını, yani p·x = m olduğunu söyler.'),
  ('Fiyatlar ve gelir veriyken faydayı en çoklaştırma probleminin çözümünden elde edilen talep fonksiyonuna ne ad verilir?', 'Marshall (sıradan) talebi', ['Hicks (telafi edilmiş) talebi', 'Koşullu girdi talebi', 'Türev talep'], 'Marshall talebi x(p, m) biçimindedir; gelir sabitken fiyat değişiminin toplam etkisini gösterir.'),
  ('Fiyatlar ve gelirin bir fonksiyonu olarak tüketicinin ulaşabileceği en yüksek fayda düzeyini gösteren fonksiyona ne ad verilir?', 'Dolaylı fayda fonksiyonu', ['Harcama fonksiyonu', 'Doğrudan fayda fonksiyonu', 'Engel fonksiyonu'], 'Dolaylı fayda v(p, m), optimal sepetin faydasıdır; bu yüzden doğrudan mallara değil fiyatlara ve gelire bağlıdır.'),
  ('Belirli bir fayda düzeyine ulaşmak için verilen fiyatlarda yapılması gereken en düşük harcamayı gösteren fonksiyona ne ad verilir?', 'Harcama fonksiyonu', ['Dolaylı fayda fonksiyonu', 'Maliyet fonksiyonu', 'Bütçe fonksiyonu'], 'Harcama fonksiyonu e(p, u), harcamayı en aza indirme probleminin değer fonksiyonudur.'),
  ('Hicks (telafi edilmiş) talep eğrisini Marshall talep eğrisinden ayıran özellik hangisidir?', 'Fiyat değişirken fayda sabit tutulur.', ['Fiyat değişirken gelir sabit tutulur.', 'Fiyat değişirken diğer malların miktarı sabit tutulur.', 'Fiyat değişirken tüketicinin tercihleri değişir.'], 'Hicks talebi yalnız ikame etkisini gösterir; tüketicinin fayda düzeyi sabit tutulacak biçimde gelir telafi edilir.'),
  ('Slutsky denklemine göre bir malın fiyat değişiminin toplam etkisi hangi iki bileşenin toplamıdır?', 'İkame etkisi ve gelir etkisi', ['Fiyat etkisi ve miktar etkisi', 'Kısa dönem ve uzun dönem etkisi', 'Arz etkisi ve talep etkisi'], 'Slutsky denklemi toplam etkiyi, göreli fiyat değişiminden doğan ikame etkisi ile satın alma gücü değişiminden doğan gelir etkisine ayırır.'),
  ('U = xy fayda fonksiyonuna sahip bir tüketicinin geliri 100 TL ve Y\'nin fiyatı 1 TL\'dir. X\'in fiyatı 2 TL\'den 1 TL\'ye düşerse X talebinin toplam artışı kaç birimdir?', '25', ['12,5', '50', '37,5'], 'Önce x = 100/(2×2) = 25, sonra x = 100/(2×1) = 50 birim; toplam etki 25 birimdir.'),
  ('Bir düşük malın fiyatı düştüğünde ikame etkisi ve gelir etkisi hangi yönde çalışır?', 'İkame etkisi talebi artırır, gelir etkisi azaltır.', ['İkisi de talebi artırır.', 'İkisi de talebi azaltır; mal bu yüzden düşük maldır.', 'İkame etkisi talebi azaltır, gelir etkisi artırır.'], 'Fiyat düşüşü göreli ucuzlama nedeniyle talebi artırır; ama reel gelir arttığı için düşük malın talebi gelir etkisiyle azalır.'),
  ('Fayda fonksiyonu U = min(x, y) olan bir tüketicide fiyat değişiminin ikame etkisi kaçtır?', 'Sıfırdır.', ['Gelir etkisine eşittir.', 'Toplam etkinin yarısıdır.', 'Her zaman negatiftir ve büyüktür.'], 'Tam tamamlayıcılarda tüketici oranı değiştiremez; bu yüzden fiyat değişiminin bütün etkisi gelir etkisinden gelir.'),
  ('Bir fiyat artışından sonra tüketicinin eski fayda düzeyine dönebilmesi için ona verilmesi gereken para tutarına ne ad verilir?', 'Telafi edici değişim', ['Eşdeğer değişim', 'Tüketici rantındaki değişim', 'Gelir etkisi'], 'Telafi edici değişim yeni fiyatlarda eski fayda düzeyini sağlayacak gelir farkını ölçer.'),
  ('Bir fiyat artışından kaçınmak için tüketicinin vazgeçmeye razı olduğu, fiyat artışıyla aynı fayda kaybını yaratan gelir tutarına ne ad verilir?', 'Eşdeğer değişim', ['Telafi edici değişim', 'Ölü ağırlık kaybı', 'Fiyat etkisi'], 'Eşdeğer değişim eski fiyatlarda, yeni fayda düzeyine eşdeğer gelir kaybını ölçer.'),
  ('Yalnızca X\'in fiyatı değişirken tüketici dengelerini birleştiren eğriye ne ad verilir?', 'Fiyat-tüketim eğrisi', ['Gelir-tüketim eğrisi', 'Engel eğrisi', 'Sözleşme eğrisi'], 'Fiyat-tüketim eğrisi farklı Px düzeylerindeki optimal sepetleri birleştirir; talep eğrisi bu eğriden türetilir.'),
  ('Fiyatlar sabitken yalnızca gelir değiştiğinde ortaya çıkan tüketici dengelerini birleştiren eğriye ne ad verilir?', 'Gelir-tüketim eğrisi', ['Fiyat-tüketim eğrisi', 'Kayıtsızlık eğrisi', 'Lorenz eğrisi ve Gini katsayısı'], 'Gelir-tüketim (gelir genişleme) eğrisi gelir arttıkça optimal sepetin nasıl değiştiğini gösterir.'),
  ('Homotetik tercihlere sahip bir tüketicinin gelir-tüketim eğrisi nasıldır?', 'Orijinden çıkan bir doğru', ['Yatay bir doğru', 'Geriye doğru bükülen bir eğri', 'Dikey bir doğru'], 'Homotetik tercihlerde gelir artınca bütün mallar aynı oranda artar; bu yüzden optimal sepetler orijinden geçen bir ışın üzerinde yer alır.'),
  ('Gelir arttıkça gelir-tüketim eğrisi X ekseninden uzaklaşıp sola doğru kıvrılıyorsa (X miktarı azalıyorsa) X için ne söylenir?', 'Bu gelir aralığında düşük maldır.', ['Lüks maldır; gelir esnekliği 1\'den büyüktür.', 'Tam ikame maldır.', 'Nötr maldır.'], 'Gelir artarken X tüketiminin azalması X\'in o aralıkta düşük mal olduğunu gösterir.'),
  ('Bir öğrencinin aylık geliri 5.000 TL\'den 6.000 TL\'ye çıkınca hazır makarna tüketimi 40 paketten 38 pakete düşmüştür. Basit yüzde değişimlerle gelir esnekliği kaçtır?', '−0,25', ['−4', '0,25', '−0,050'], 'Gelir %20 artmış, miktar %5 azalmıştır: −5 / 20 = −0,25. Negatif işaret malın düşük mal olduğunu gösterir.'),
  ('Q = 100 − 2P talep fonksiyonunda tüketicilerin bu mala yaptığı toplam harcama hangi fiyatta en yüksek olur?', '25 TL', ['50 TL', '20 TL', '12,5 TL'], 'Harcama P·Q = 100P − 2P² olup türevi 100 − 4P = 0\'dan P = 25 bulunur; bu noktada esneklik −1\'dir.'),
  ('Doğrusal bir talep eğrisinin tam orta noktasında fiyat esnekliği kaçtır?', '−1', ['0', '−∞', '−0,5'], 'Orta noktada P/Q oranı eğimin tersine eşit olur ve esneklik −1 çıkar; üst yarıda esnek, alt yarıda inelastiktir.'),
  ('Tüketicinin tercihlerini fayda fonksiyonu yerine gözlenen satın alma kararlarından çıkarmayı amaçlayan ve 1938\'de Paul Samuelson\'ın ortaya attığı yaklaşım hangisidir?', 'Açıklanmış tercih kuramı', ['Beklenen fayda kuramı', 'Kardinal fayda kuramı', 'Kahneman-Tversky beklenti kuramı'], 'Samuelson, yalnızca gözlenen seçimlere dayanan ve fayda kavramına ihtiyaç duymayan bir talep kuramı önerdi.'),
  ('Cari dönem miktarlarını ağırlık olarak kullanan fiyat endeksine ne ad verilir?', 'Paasche endeksi', ['Laspeyres endeksi', 'Fisher ideal endeksi', 'Törnqvist endeksi'], 'Paasche endeksi cari sepeti iki dönem fiyatlarıyla değerler: Σp₁q₁ / Σp₀q₁.'),
  ('Laspeyres ve Paasche fiyat endekslerinin geometrik ortalaması olarak hesaplanan endekse ne ad verilir?', 'Fisher ideal endeksi', ['Divisia sürekli zaman endeksi', 'Carli endeksi', 'Sauerbeck endeksi'], 'Irving Fisher\'ın \'ideal\' endeksi √(Laspeyres × Paasche) olarak hesaplanır ve iki endeksin yanlılıklarını dengeler.'),
  ('Emek-boş zaman modelinde günlük 24 saati olan ve saat ücreti w olan bir kişinin bütçe doğrusunun eğimi (yatay eksende boş zaman) neyi gösterir?', 'Bir saat boş zamanın fırsat maliyeti olan ücreti', ['Kişinin emek dışı gelirini', 'Kişinin günlük toplam tüketim harcamasının tamamını', 'Kişinin çalışma saatlerinin sayısını'], 'Bir saat fazladan boş zaman w kadar tüketimden vazgeçmek demektir; bu yüzden bütçe doğrusunun eğimi −w\'dir.'),
  ('Emek dışı geliri olmayan bir kişinin fayda fonksiyonu U = C · L\'dir (C tüketim, L boş zaman). Günde 24 saati ve saat ücreti 20 TL ise kaç saat çalışır?', '12', ['8', '16', '10,5'], 'U = CL\'de tam gelirin yarısı boş zamana gider: L = (24 × 20)/2 ÷ 20 = 12 saat boş zaman, 12 saat çalışma.'),
  ('Bir kişinin hiç çalışmamakla çalışmaya başlamak arasında kayıtsız kaldığı ücret düzeyine ne ad verilir?', 'Rezervasyon ücreti', ['Yasal asgari ücret düzeyi', 'Etkinlik ücreti', 'Denge ücreti'], 'Rezervasyon ücreti, sıfır çalışma noktasındaki marjinal ikame oranına eşittir; piyasa ücreti bunun üzerindeyse kişi işgücüne katılır.'),
  ('Boş zamanın normal mal olduğu bir kişiye her ay koşulsuz sabit bir nakit transfer verilirse çalışma saatleri için ne beklenir?', 'Azalır.', ['Artar.', 'Değişmez.', 'Önce artar sonra azalır.'], 'Götürü transfer saf gelir etkisi yaratır; boş zaman normal mal olduğundan daha çok boş zaman, yani daha az çalışma seçilir.'),
  ('Ücret arttığında ikame etkisi çalışma saatlerini nasıl etkiler?', 'Her zaman artırır.', ['Her zaman azaltır.', 'Boş zaman normal malsa azaltır.', 'Hiç etkilemez.'], 'Ücret artışı boş zamanın fırsat maliyetini yükseltir; ikame etkisi daima daha az boş zaman, yani daha çok çalışma yönündedir.'),
  ('Günlük 8 saati aşan her saat için ücretin 1,5 katının ödendiği fazla mesai uygulaması bütçe doğrusunu nasıl etkiler?', '8 saatlik çalışmaya karşılık gelen noktadan itibaren doğruyu dikleştirir.', ['Doğruyu tümüyle içe doğru paralel kaydırır.', 'Doğruyu 8. saatten sonra yatıklaştırır.', 'Doğruda hiçbir değişiklik yapmaz.'], 'Fazla mesaide bir saat boş zamanın fırsat maliyeti 1,5w olur; boş zaman 16 saatin altına indiğinde bütçe doğrusu daha dik hâle gelir.'),
  ('İki dönemli Fisher modelinde bir kişinin bu yıl 100.000 TL, gelecek yıl 110.000 TL geliri vardır ve faiz oranı %10\'dur. Bu kişinin ömür boyu gelirinin bugünkü değeri kaç TL\'dir?', '200.000', ['210.000', '199.000', '220.000,0'], '100.000 + 110.000 / 1,10 = 100.000 + 100.000 = 200.000 TL.'),
  ('İki dönemli zamanlar arası bütçe doğrusunun eğimi (yatay eksende bugünkü tüketim) neye eşittir?', '−(1 + r)', ['−r', '−1 /', '−1'], 'Bugün 1 TL daha az tüketen kişi bunu faizle değerlendirip yarın 1 + r TL fazla tüketebilir.'),
  ('Faiz oranı değiştiğinde zamanlar arası bütçe doğrusu hangi nokta etrafında döner?', 'Kişinin her iki dönemdeki gelirini gösteren başlangıç (donatım) noktası', ['Bugünkü tüketimin sıfır olduğu nokta', 'Gelecek tüketimin sıfır olduğu nokta', 'Orijin'], 'Hiç borç alıp vermeyen kişi her faiz oranında gelirlerini tüketebilir; bu yüzden donatım noktası her zaman doğru üzerindedir.'),
  ('Bir kişinin borçlanmasına hiç izin verilmiyorsa zamanlar arası bütçe kümesi nasıl değişir?', 'Bugünkü tüketim bugünkü gelirle sınırlanır; doğru donatım noktasında kesilir.', ['Bütçe doğrusu borçlanma olmadığı için dışa doğru paralel olarak kayar.', 'Bütçe doğrusu yataylaşır.', 'Kişi gelecekte hiç tüketim yapamaz.'], 'Likidite kısıtı, donatım noktasının sağındaki kısmı (borçlanma bölgesini) bütçe kümesinden çıkarır.'),
  ('Zamanlar arası tercih ve faiz kuramını 1930\'da yayımladığı \'The Theory of Interest\' adlı kitabında sistematik hâle getiren iktisatçı kimdir?', 'Irving Fisher', ['Eugen von Böhm-Bawerk', 'Knut Wicksell', 'Frank Knight'], 'Fisher, sabırsızlık ve yatırım fırsatlarının faizi birlikte belirlediğini gösteren iki dönemli modeli bu eserinde geliştirdi.'),
  ('Yazı gelirse 100 TL kazanılan, tura gelirse hiçbir şey kazanılmayan adil bir yazı-tura oyununun beklenen değeri kaç TL\'dir?', '50', ['100', '25', '75,5'], 'Beklenen değer = 0,5 × 100 + 0,5 × 0 = 50 TL.'),
  ('Riskli seçimleri, olası sonuçların faydalarının olasılıklarla ağırlıklı ortalamasına göre değerlendiren kuram hangisidir?', 'Beklenen fayda kuramı', ['Açıklanmış tercih kuramı', 'Beklenti (prospect) kuramı', 'Oyun kuramındaki minimaks ilkesi'], 'Beklenen fayda kuramında piyango, Σ pᵢ · u(xᵢ) değerine göre sıralanır.'),
  ('Beklenen fayda kuramını aksiyomatik olarak temellendiren 1944 tarihli \'Theory of Games and Economic Behavior\' kitabının yazarları kimlerdir?', 'John von Neumann ve Oskar Morgenstern', ['John Nash ve Reinhard Selten ile John Harsanyi', 'Kenneth Arrow ve Gérard Debreu', 'Daniel Bernoulli ve Gabriel Cramer'], 'Von Neumann ve Morgenstern bu eserde rasyonel tercih aksiyomlarından beklenen fayda temsilini türetti.'),
  ('Fayda fonksiyonu u(w) = √w olan bir kişi %50 olasılıkla 100 TL, %50 olasılıkla 0 TL veren bir piyangoya sahiptir. Bu piyangonun beklenen faydası kaçtır?', '5', ['50', '10', '7,07'], 'Beklenen fayda = 0,5 × √100 + 0,5 × √0 = 0,5 × 10 = 5.'),
  ('Bir piyangonun beklenen değeri 50 TL, kesinlik eşdeğeri 25 TL\'dir. Bu kişinin risk primi ve risk tutumu hangisidir?', '25 TL; riskten kaçınan', ['25 TL; riski seven', '75 TL; riskten kaçınan bir kişi', '0 TL; riske karşı nötr'], 'Risk primi = beklenen değer − kesinlik eşdeğeri = 25 TL. Pozitif prim riskten kaçınmayı gösterir.'),
  ('Riskten kaçınan bir kişinin servete bağlı fayda fonksiyonu hangi biçimdedir?', 'İçbükey', ['Dışbükey', 'Doğrusal', 'Basamaklı'], 'İçbükey faydada marjinal fayda azalır; beklenen değerin faydası, piyangonun beklenen faydasından büyük olur.'),
  ('Beklenen değeri aynı olan iki seçenekten daha riskli olanı her zaman tercih eden kişinin fayda fonksiyonu nasıldır?', 'Dışbükey (marjinal faydası artan)', ['İçbükey (marjinal faydası azalan)', 'Doğrusal', 'Yatay (servetten bağımsız sabit)'], 'Riski seven kişinin kesinlik eşdeğeri beklenen değerden büyüktür; bu da dışbükey bir fayda fonksiyonunu gerektirir.'),
  ('Serveti 100.000 TL olan birinin evinde yılda %10 olasılıkla 40.000 TL\'lik hasar oluşabiliyor. Aktüeryal olarak adil bir tam sigortanın primi kaç TL\'dir?', '4.000', ['40.000', '10.000', '6.000'], 'Adil prim beklenen kayba eşittir: 0,10 × 40.000 = 4.000 TL.'),
  ('Aktüeryal olarak adil sigorta sunulduğunda riskten kaçınan bir tüketicinin en iyi seçimi hangisidir?', 'Kaybın tamamını sigortalatmak', ['Hiç sigorta yaptırmamak', 'Kaybın yarısını sigortalatmak', 'Kaybın iki katı tutarında sigorta yaptırmak'], 'Adil primle tam sigorta, beklenen serveti değiştirmeden riski tamamen ortadan kaldırır; riskten kaçınan kişi için bu en yüksek beklenen faydayı verir.'),
  ('Yazı gelene kadar atılan bir parada ödülün her atışta iki katına çıktığı oyunun beklenen değeri sonsuz olduğu hâlde insanların bu oyuna küçük bir tutardan fazlasını ödemek istememesi hangi paradoks olarak bilinir?', 'St. Petersburg paradoksu', ['Allais paradoksu', 'Ellsberg paradoksu', 'Condorcet oylama paradoksu'], 'Beklenen değer sonsuz olsa da insanlar düşük olasılıklı dev ödüllere sınırlı değer biçer; paradoks beklenen değer ölçütünün yetersizliğini gösterir.'),
  ('St. Petersburg paradoksuna 1738\'de servetin logaritmik faydası gibi azalan marjinal faydalı bir fayda fonksiyonu önererek çözüm getiren bilim insanı kimdir?', 'Daniel Bernoulli', ['Blaise Pascal', 'Pierre-Simon Laplace', 'Jeremy Bentham'], 'Daniel Bernoulli, beklenen değer yerine beklenen faydanın kullanılmasını önerdi; log faydada oyunun beklenen faydası sonludur.'),
  ('Beklenti kuramında sonuçlar neye göre değerlendirilir?', 'Bir referans noktasına göre kazanç ya da kayıp olarak', ['Kişinin sahip olduğu toplam servetin mutlak düzeyine göre', 'Piyasa fiyatlarının ortalamasına göre', 'Yalnızca beklenen değere göre'], 'Kahneman ve Tversky\'nin beklenti kuramında değer fonksiyonu servetin düzeyine değil, referans noktasından sapmalara tanımlıdır.'),
  ('Beklenti kuramındaki değer fonksiyonunun biçimi için hangisi doğrudur?', 'Kazançlarda içbükey, kayıplarda dışbükeydir.', ['Kazançlarda dışbükey, kayıplarda içbükeydir.', 'Her yerde doğrusaldır; kazanç ve kayıp simetriktir.', 'Her yerde içbükeydir.'], 'Bu biçim insanların kazançlarda riskten kaçındığını, kayıplarda ise riski göze aldığını açıklar.'),
  ('Aynı salgın programının \'600 kişiden 200\'ü kurtulur\' biçiminde sunulmasının, \'600 kişiden 400\'ü ölür\' biçiminde sunulmasından farklı seçimlere yol açması hangi etkiyi gösterir?', 'Çerçeveleme etkisi', ['Tuzak etkisi', 'Batık maliyet etkisi', 'Sürü etkisi'], 'Tversky ve Kahneman\'ın 1981 deneyinde içerik aynı olduğu hâlde kazanç ya da kayıp diliyle sunulması tercihleri tersine çevirdi.'),
  ('Bir markette 24 çeşit reçel sunulan standın 6 çeşit sunulana göre daha çok ilgi çekip daha az satış yapması deneyi hangi olguyu örnekler?', 'Seçenek fazlalığı', ['Ölçek ekonomisi', 'Fiyat farklılaştırması ve paket satış', 'Bandwagon etkisi'], 'Iyengar ve Lepper\'ın deneyi, seçenek sayısı arttıkça karar vermenin zorlaşabildiğini ve satın almanın azalabildiğini gösterdi.'),
  ('Üstel (sabit oranlı) iskonto kullanan bir kişide iskonto çarpanı dönem başına 0,9\'dur. İki dönem sonra alınacak 100 TL\'nin bugünkü değeri bu kişi için kaç TL\'dir?', '81', ['90', '80', '72,9'], 'Üstel iskontoda 100 × 0,9² = 81 TL olur.'),
  ('Üstel iskonto kullanan birinin tercihleri için hangisi doğrudur?', 'Zaman içinde tutarlıdır; bugün yaptığı plan yarın da en iyi plan olarak kalır.', ['Hep bugünü geleceğe tercih eder ve plan yapamaz.', 'İleride vazgeçeceği planları sürekli yapar ve sonra bunlardan döner.', 'Kayıpları kazançlardan daha ağır tartar.'], 'Sabit oranlı iskontoda iki tarih arasındaki göreli ağırlık yalnızca aradaki süreye bağlıdır; bu nedenle tercihler zamanla tersine dönmez.'),
  ('1960\'lar ve 1970\'lerde Stanford\'da yapılan bir deneyde çocuklara bir şekeri hemen yemek ya da biraz bekleyip iki şeker almak arasında seçim sunuldu. Bu ünlü çalışma hangi kavramla ilgilidir?', 'Hazzı erteleme ve öz denetim', ['Ölçek ekonomisi', 'Fiyat esnekliği ve talep kanunu', 'Gösteriş tüketimi'], 'Walter Mischel\'in \'marshmallow\' deneyi, anlık ödül ile daha büyük gecikmiş ödül arasındaki öz denetimi inceledi.'),
  ('Bir ürünü başkaları satın aldığı için talebin artmasına (\'moda olanı alma\') Harvey Leibenstein\'in verdiği ad nedir?', 'Bandwagon (çoğunluğa uyma) etkisi', ['Snop etkisi', 'Giffen etkisi', 'Ratchet (mandal) etkisi ve alışkanlık'], 'Leibenstein 1950\'de bandwagon, snop ve Veblen etkilerini ayrı ayrı tanımladı; bandwagon etkisinde başkalarının tüketimi talebi artırır.'),
  ('Telefon ya da mesajlaşma uygulaması gibi ağ etkisi güçlü ürünlerde yeni bir firmanın başarılı olabilmesi için ulaşması gereken en az kullanıcı sayısına ne ad verilir?', 'Kritik kütle', ['Asgari etkin ölçek', 'Başabaş noktası', 'Doygunluk noktası'], 'Ağ etkili ürünlerde belirli bir kullanıcı sayısına ulaşılmadan ürünün değeri düşük kalır; kritik kütle aşılınca talep kendi kendini besler.'),
  ('Kelvin Lancaster\'ın 1966\'da geliştirdiği tüketici kuramına göre tüketiciler mallardan doğrudan değil neyden fayda elde eder?', 'Malların sahip olduğu niteliklerden', ['Malların piyasa fiyatlarından', 'Malları üreten firmaların büyüklüğünden ve ününden', 'Malların ithal ya da yerli olmasından'], 'Lancaster\'a göre bir otomobil hız, güvenlik ve konfor gibi niteliklerin demetidir; talep bu niteliklere yöneliktir.'),
  ('Gary Becker\'ın zaman tahsisi kuramına göre bir sinema filmini izlemenin \'tam fiyatı\' hangi unsurları içerir?', 'Bilet fiyatı ile harcanan zamanın fırsat maliyetini', ['Yalnızca bilet fiyatını', 'Bilet fiyatı ile sinemanın kira ve personel giderlerini', 'Yalnızca harcanan zamanı'], 'Becker\'a göre hane, piyasa mallarını ve zamanını birleştirerek \'temel ürünler\' üretir; zamanın değeri tüketimin maliyetine eklenir.'),
  ('Saat ücreti 50 TL olan biri 100 TL\'lik bilet alıp toplam 3 saat süren bir konsere gidiyor. Becker\'ın yaklaşımına göre bu konserin tam fiyatı kaç TL\'dir?', '250', ['150', '100', '300,0'], 'Tam fiyat = 100 + 3 × 50 = 250 TL.'),
  ('Hermann Heinrich Gossen\'in adıyla anılan birinci yasa neyi ifade eder?', 'Bir maldan tüketildikçe ek birimin sağladığı tatminin azaldığını', ['Tüketicinin her mala eşit para harcadığını', 'Fiyat düştükçe talebin arttığını', 'Aile geliri arttıkça gıdaya ayrılan harcama payının düştüğünü'], 'Gossen\'in 1854\'te yayımladığı eserdeki birinci yasa azalan marjinal fayda ilkesidir.'),
  ('Gossen\'in ikinci yasası olarak bilinen ilke hangisidir?', 'Faydanın en yüksek olması için her mala harcanan son liranın marjinal faydasının eşit olması', ['Bir maldan tüketildikçe marjinal faydanın azalması', 'Talebin fiyatla ters yönde değişmesi', 'Malların değerinin içerdikleri emeğe eşit olması'], 'İkinci yasa eş marjinal ilkesidir: MUx/Px = MUy/Py; böylece bütçe en yüksek faydayı verecek biçimde dağıtılır.'),
  ('Bir tüketici kitaplara harcadığı son liradan 4 birim, sinemaya harcadığı son liradan 7 birim fayda alıyorsa Gossen\'in ikinci yasasına göre ne yapmalıdır?', 'Harcamasını kitaptan sinemaya kaydırmalıdır.', ['Harcamasını sinemadan kitaba kaydırmalıdır.', 'Her ikisine de daha çok harcayıp tasarrufunu azaltmalıdır.', 'Harcama dağılımını değiştirmemelidir.'], 'Sinemaya harcanan lira daha çok fayda getirdiği için oraya kayılmalıdır; azalan marjinal fayda iki oranı eşitleyene kadar bu sürer.'),
  ('Faydasını para cinsinden ölçen ve net faydasını (ödediği fiyat düşüldükten sonra kalan faydayı) en yükseğe çıkarmaya çalışan bir tüketici, fiyatı pozitif bir maldan ne zamana kadar tüketir?', 'Marjinal faydanın fiyatın değerine (para cinsinden) eşitlendiği noktaya kadar', ['Marjinal faydası negatif olana kadar', 'Toplam faydanın sıfırlandığı noktaya kadar', 'Ortalama faydanın en yüksek olduğu tüketim düzeyine ulaşılana kadar'], 'Ek bir birim, para cinsinden marjinal faydası fiyatını aştığı sürece alınır; eşitlendiği noktada durulur.'),
  ('Üretim fonksiyonu en doğru biçimde nasıl tanımlanır?', 'Verili teknolojiyle her girdi bileşiminden elde edilebilecek en yüksek çıktıyı gösteren ilişki', ['Bir firmanın her çıktı düzeyinde katlandığı en düşük toplam maliyeti gösteren ilişki ve eğrisi', 'Bir malın fiyatı ile arz edilen miktarı arasındaki ilişki', 'Firmanın kârını girdi fiyatlarına bağlayan ilişki'], 'Üretim fonksiyonu teknik bir ilişkidir; girdilerin etkin kullanıldığı varsayımıyla ulaşılabilecek azami çıktıyı verir.'),
  ('Q = 2K + 3L biçimindeki bir üretim fonksiyonunda emek ile sermaye arasındaki ilişki hangisidir?', 'Tam ikamedirler; biri hiç kullanılmadan da üretim yapılabilir.', ['Tam tamamlayıcıdırlar; sabit oranda kullanılmaları gerekir.', 'Her ikisi de üretim için zorunludur; biri sıfırsa çıktı da sıfır olur.', 'Emek arttıkça sermayenin marjinal ürünü artar.'], 'Doğrusal üretim fonksiyonunda girdiler sabit oranda birbirinin yerine geçer; eş ürün eğrileri düz doğrulardır.'),
  ('Q = min(K/2, L/3) üretim fonksiyonuna sahip bir firma 10 birim sermaye ve 12 birim emekle kaç birim üretebilir?', '4', ['5', '22', '3,5'], 'min(10/2, 12/3) = min(5, 4) = 4. Emek kısıtlayıcıdır; sermayenin bir kısmı atıl kalır.'),
  ('Sabit oranlı (Leontief) üretim fonksiyonunda, diğer girdi sabitken yalnız bir girdinin artırılmasının etkisi hangisidir?', 'Çıktı artmaz; fazla girdi atıl kalır.', ['Çıktı girdiyle aynı oranda artar.', 'Çıktı artar ama azalan oranda artmaya devam eder.', 'Çıktı azalır.'], 'Leontief teknolojisinde girdiler belirli bir oranda birlikte kullanılmak zorundadır; kısıtlayıcı olmayan girdiyi artırmak üretimi değiştirmez.'),
  ('Q = 4√(K·L) üretim fonksiyonunda firma 4 birim sermaye ve 9 birim emek kullanırsa çıktı kaç birim olur?', '24', ['52', '36', '12,5'], '√(4 × 9) = 6; 4 × 6 = 24 birim.'),
  ('Q = A·K^α·L^β biçimindeki üretim fonksiyonu, adını 1928\'de ABD imalat sanayisi verileriyle test eden hangi iki kişiden alır?', 'Charles Cobb ve Paul Douglas', ['Kenneth Arrow ve Robert Solow', 'Wassily Leontief ve Simon Kuznets', 'John Hicks ve Roy Allen'], 'Matematikçi Charles Cobb ile iktisatçı Paul Douglas 1928\'de bu fonksiyonu ABD imalat verilerine uyguladı.'),
  ('Q = K^0,5 · L^0,5 fonksiyonunda sermaye sabitken emek %10 artırılırsa çıktı yaklaşık yüzde kaç artar?', '5', ['10', '2,5', '50,0'], 'Cobb-Douglas\'ta emeğin üssü emeğin çıktı esnekliğidir: 0,5 × %10 ≈ %5.'),
  ('Cobb-Douglas üretim fonksiyonunda girdilerden biri sıfır olursa ne olur?', 'Çıktı sıfır olur.', ['Çıktı yarıya iner.', 'Diğer girdi tek başına aynı miktarı üretir.', 'Çıktı sonsuza gider.'], 'Çarpımsal yapı nedeniyle K ya da L sıfırsa Q = 0 olur; her iki girdi de üretim için zorunludur.'),
  ('Q = K^0,5 · L^0,5 üretim fonksiyonuna sahip bir firma bütün girdilerini 3 katına çıkarırsa çıktı ne kadar olur?', '3 katına çıkar.', ['9 katına çıkar.', 'Yaklaşık 1,7 katına çıkar.', 'Değişmez.'], 'Üslerin toplamı 1 olduğu için fonksiyon birinci dereceden homojendir; ölçeğe göre sabit getiri vardır.'),
  ('Ölçeğe göre getiri kavramı neyi ölçer?', 'Bütün girdiler aynı oranda değiştiğinde çıktının ne oranda değiştiğini', ['Yalnızca tek bir girdi değiştiğinde çıktının ne kadar ve hangi yönde değiştiğini', 'Fiyatlar değiştiğinde firmanın kârının ne kadar değiştiğini', 'Talep değiştiğinde firmanın satışlarının ne kadar değiştiğini'], 'Ölçeğe göre getiri uzun döneme ait bir kavramdır ve bütün girdilerin orantılı değişimine çıktının tepkisini gösterir.'),
  ('Bir firmada ölçeğe göre azalan getirinin en sık gösterilen nedenlerinden biri hangisidir?', 'Firma büyüdükçe yönetim ve koordinasyonun güçleşmesi', ['Makinelerin daha verimli çalışması', 'İşçilerin uzmanlaşması', 'Toplu girdi alımlarında tedarikçilerden indirim alınabilmesi'], 'Diğer etkenler ölçek büyüdükçe verimi artırırken, yönetim kapasitesi gibi kolay çoğaltılamayan unsurlar verimi düşürebilir.'),
  ('Q = K^0,5 · L^0,5 üretim fonksiyonuna sahip bir firma 8 birim sermaye ve 2 birim emek kullanıyor. Bu noktada emeğin sermaye yerine teknik ikame oranı (MPL/MPK) kaçtır?', '4', ['0,25', '16', '2,50'], 'Eşit üslü Cobb-Douglas\'ta MRTS = K/L = 8/2 = 4; bir işçi 4 birim sermayenin yerini tutar.'),
  ('Q = 2K + 3L üretim fonksiyonunda emeğin sermaye yerine teknik ikame oranı (MPL/MPK) için hangisi doğrudur?', 'Her noktada 1,5\'tir.', ['Her noktada 2/3\'tür.', 'Emek arttıkça azalır.', 'Sermaye arttıkça artar.'], 'MPL = 3 ve MPK = 2 sabittir; oranları her noktada 3/2 = 1,5\'tir ve eş ürün eğrileri düz doğrulardır.'),
  ('Eş ürün eğrilerinin orijine göre dışbükey olmasının nedeni hangisidir?', 'Azalan marjinal teknik ikame oranı', ['Ölçeğe göre artan getiri ve uzmanlaşma', 'Girdi fiyatlarının sabit olması', 'Toplam maliyetin sabit olması'], 'Emek arttıkça bir birim emeğin yerini tutabilecek sermaye miktarı azalır; bu da eğrinin dışbükey biçimini verir.'),
  ('Teknik ikame oranı (MRTS) ile tüketicinin marjinal ikame oranı (MRS) arasındaki temel benzerlik hangisidir?', 'İkisi de eğrilerin eğimini ve iki unsur arasındaki takas oranını gösterir.', ['İkisi de fiyatlara eşittir.', 'İkisi de yalnızca para birimiyle ölçülen büyüklüklerdir.', 'İkisi de zamanla sabit kalır.'], 'MRS kayıtsızlık eğrisinin, MRTS eş ürün eğrisinin eğimidir; biri faydayı, diğeri çıktıyı sabit tutan takas oranıdır.'),
  ('Cobb-Douglas üretim fonksiyonunun ikame esnekliği kaçtır?', '1', ['0', 'Sonsuz', 'Üslerin toplamı'], 'Cobb-Douglas\'ta MRTS, K/L ile orantılıdır; ikisinin yüzde değişimleri her zaman eşit olur ve σ = 1 çıkar.'),
  ('Emeğin değişken, sermayenin sabit olduğu kısa dönemde üretimin birinci evresi nerede sona erer?', 'Emeğin ortalama ürününün en yüksek olduğu noktada', ['Emeğin marjinal ürününün en yüksek olduğu dönüm noktasında', 'Toplam ürünün en yüksek olduğu noktada', 'Emeğin marjinal ürününün sıfır olduğu noktada'], 'Birinci evre ortalama ürün artarken sürer; AP\'nin zirvesinde (MP = AP) ikinci evre başlar.'),
  ('Kısa dönemde rasyonel bir firma hangi üretim evresinde çalışır?', 'İkinci evrede', ['Birinci evrede', 'Üçüncü evrede', 'Evrelerden bağımsız olarak her yerde'], 'Birinci evrede ek işçi ortalama verimi artırdığı için durmak mantıksızdır; üçüncü evrede ise marjinal ürün negatiftir. Rasyonel bölge ikinci evredir.'),
  ('Sabit bir tarlaya giderek artan sayıda işçi eklendiğinde toplam ürün hâlâ artarken hangi büyüklük kesinlikle pozitiftir?', 'Emeğin marjinal ürünü', ['Ortalama ürünün değişim hızı', 'Sabit girdinin marjinal ürünü', 'Marjinal ürünün değişim hızı'], 'Toplam ürün artıyorsa ek işçinin katkısı, yani marjinal ürün, sıfırdan büyüktür.'),
  ('Belirli bir çıktıyı en düşük maliyetle üretmek isteyen firma, iki girdiyi hangi koşul sağlanana kadar ayarlar?', 'Her girdiye harcanan son liranın marjinal ürününün eşit olması', ['Her iki girdinin marjinal ürünlerinin fiyatları dikkate alınmadan birbirine eşitlenmesi', 'Her iki girdiye eşit para harcanması', 'Her iki girdinin fiyatlarının eşit olması'], 'Maliyet en aza indirildiğinde eş ürün eğrisi eş maliyet doğrusuna teğettir: MRTS = w/r, yani MPL/w = MPK/r.'),
  ('Q = K^0,5 · L^0,5 üretim fonksiyonuna sahip bir firmada ücret 4 TL, sermayenin kirası 1 TL\'dir. Maliyeti en aza indiren girdi oranı (K/L) kaçtır?', '4', ['1/4', '2', '1'], 'Eşit üslü Cobb-Douglas\'ta MRTS = K/L\'dir; MRTS = w/r = 4 koşulu K/L = 4 verir.'),
  ('Eş maliyet doğrusunun eğimi (yatay eksende emek) neyi gösterir?', 'Ücretin sermayenin kirasına oranını', ['Emeğin marjinal ürününü', 'Firmanın girdilere ayırdığı toplam bütçenin büyüklüğünü', 'Ölçeğe göre getiri derecesini'], 'Eş maliyet doğrusu wL + rK = C\'dir; eğimi −w/r olup piyasanın iki girdi arasındaki takas oranını gösterir.'),
  ('Toplam 1.000 TL bütçesi olan bir firma için işçi başına ücret 50 TL, makine başına kira 100 TL\'dir. Firma yalnız emek kullanırsa en çok kaç işçi çalıştırabilir?', '20', ['10', '50', '15,5'], '1.000 / 50 = 20 işçi.'),
  ('Bütün girdi fiyatları iki katına çıkarsa, belirli bir çıktıyı en düşük maliyetle üretmenin maliyeti nasıl değişir?', 'İki katına çıkar.', ['Değişmez.', 'Dört katına çıkar.', 'Yarıya iner.'], 'Maliyet fonksiyonu girdi fiyatlarında birinci dereceden homojendir; göreli fiyatlar değişmediğinden aynı girdi bileşimi iki katı paraya mal olur.'),
  ('Farklı çıktı düzeyleri için maliyeti en aza indiren girdi bileşimlerini birleştiren eğriye ne ad verilir?', 'Genişleme yolu', ['Sırt doğrusu', 'Eş ürün eğrisi', 'Fiyat-tüketim eğrisi'], 'Girdi fiyatları sabitken çıktı arttıkça teğet noktaların izlediği yol genişleme yoludur.'),
  ('Q = min(K, L) üretim fonksiyonuna sahip bir firmada ücret 3 TL, sermayenin kirası 2 TL ise Q birim çıktının en düşük toplam maliyeti nedir?', '5Q', ['3Q', '2,5Q', '6Q'], 'Her çıktı birimi için 1 birim K ve 1 birim L gerekir; birim maliyet 3 + 2 = 5 TL, toplam maliyet 5Q olur.'),
  ('İşçi ücretleri yükselirken bir otomobil fabrikasının montaj hattında robot kullanımını artırması üretim kuramının hangi öngörüsüne uygundur?', 'Göreli pahalanan girdinin yerine diğer girdinin ikame edilmesi', ['Ölçeğe göre artan getirinin ortaya çıkması', 'Tüketici talebinin artmasıyla üretimin kendiliğinden büyümesi', 'Sabit maliyetlerin çıktıya yayılması'], 'w/r yükseldiğinde maliyeti en aza indiren K/L oranı artar; firma eş ürün eğrisi boyunca sermaye yoğun bir noktaya kayar.'),
  ('Toplam maliyet fonksiyonu TC = 100 + 4Q + Q² olan bir firmanın 5. birimdeki marjinal maliyeti (türevle) kaç TL\'dir?', '14', ['29', '9', '24,5'], 'MC = dTC/dQ = 4 + 2Q; Q = 5\'te 4 + 10 = 14 TL.'),
  ('Sabit gideri 100 TL olan bir atölyede değişken gider, üretilen adet sayısının karesine eşittir. Birim başına düşen toplam gider kaç adette en azdır?', '10', ['5', '20', '100'], 'ATC = 100/Q + Q; türevi −100/Q² + 1 = 0\'dan Q = 10 bulunur. Bu noktada MC = 2Q = 20 = ATC olur.'),
  ('Marjinal maliyetin ortalama değişken maliyetin altında olduğu bir üretim aralığında ortalama değişken maliyet nasıl hareket eder?', 'Azalır.', ['Artar.', 'Sabit kalır.', 'Sıfıra iner.'], 'Ortalamaya eklenen birim ortalamadan düşükse ortalama düşer; marjinal-ortalama ilişkisinin genel kuralıdır.'),
  ('Kısa dönemde ortalama toplam maliyet ile ortalama değişken maliyet eğrileri arasındaki dikey uzaklık üretim arttıkça nasıl değişir?', 'Daralır; çünkü bu fark ortalama sabit maliyettir.', ['Genişler; çünkü değişken maliyet artar.', 'Sabit kalır.', 'Önce daralır, belli bir üretim düzeyinden sonra yeniden genişler.'], 'ATC − AVC = AFC\'dir; sabit maliyet daha çok birime yayıldıkça bu fark küçülür ama sıfıra inmez.'),
  ('Kısa dönem marjinal maliyet eğrisi azalan verimler başladığında nasıl davranır?', 'Yükselmeye başlar.', ['Düşmeye başlar.', 'Sabit kalır.', 'Ortalama sabit maliyete eşitlenir.'], 'MC = w / MPL\'dir; ek işçinin marjinal ürünü düştüğünde bir birim çıktının ek maliyeti artar.'),
  ('Bir firma küçük bir tesisle 1.000 birimi birim başına 30 TL\'ye, büyük bir tesisle 25 TL\'ye üretebiliyor. Uzun dönemde 1.000 birim üretmeyi planlayan firma hangi tesisi seçer ve neden?', 'Büyük tesisi; uzun dönemde birim maliyeti en düşük tesis seçilir.', ['Küçük tesisi; uzun dönemde küçük tesisler esnek olduğu için her zaman daha ucuzdur.', 'İkisini birlikte; uzun dönemde tesisler toplanır.', 'Kararı erteler; uzun dönemde üretim durur.'], 'Uzun dönem planlamasında bütün tesis büyüklükleri seçilebilir; firma o çıktıyı en ucuza üreten tesisi kurar.'),
  ('Kapsam ekonomisinin derecesi negatif çıkan bir firma için ne önerilir?', 'Ürünleri ayrı firmalarda üretmek daha ucuzdur.', ['Ürünleri birlikte üretmek daha ucuzdur.', 'Firmanın ölçeğini büyütmesi gerekir.', 'Firmanın ürün fiyatlarını yükseltmesi ve ölçeğini küçültmesi gerekir.'], 'Negatif derece, ortak üretimin ayrı üretimden pahalı olduğunu, yani kapsam eksi ekonomisini gösterir.'),
  ('%80\'lik öğrenme eğrisinde birikimli üretim her ikiye katlandığında birim başına emek süresi önceki düzeyin %80\'ine iner. İlk uçağın montajı 100 saat sürmüşse 4. uçağınki kaç saat sürer?', '64', ['80', '60', '51,2'], 'İki katlanma vardır: 100 × 0,8 × 0,8 = 64 saat.'),
  ('Bir firmanın yeni bir ürün hattı açmaya karar verirken yalnızca bu karar nedeniyle ortaya çıkacak ek maliyetlere ne ad verilir?', 'Artırımsal (ek) maliyet', ['Batık maliyet', 'Tarihi maliyet', 'Ortalama sabit maliyet ve amortisman'], 'Karar analizinde ilgili maliyet, kararla birlikte değişen artırımsal maliyettir; önceden katlanılmış maliyetler hesaba katılmaz.'),
  ('Rekabetçi bir firmada ürün fiyatı artarsa, diğer koşullar sabitken emeğin marjinal ürün değeri eğrisi ve emek talebi nasıl değişir?', 'Sağa kayar; firma daha çok işçi çalıştırır.', ['Sola kayar; firma daha az işçi çalıştırır.', 'Değişmez.', 'Yatay hâle gelir; çünkü ücret sabittir.'], 'Marjinal ürün değeri = P × MPL olduğundan fiyat artışı her işçinin katkısının değerini yükseltir; talep eğrisi sağa kayar.'),
  ('Q = A · K^0,5 · L^0,5 üretim fonksiyonunda teknoloji katsayısı A %10 artarsa, aynı girdilerle çıktı ne kadar artar?', '%10', ['%5', '%20', '%2,5'], 'A çarpımsal bir katsayı olduğundan girdiler sabitken çıktı A ile aynı oranda, yani %10 artar.'),
  ('Teknolojik ilerlemeyi \'süreç yeniliği\' ve \'ürün yeniliği\' olarak ayırırken süreç yeniliğine örnek hangisidir?', 'Aynı ürünü daha az girdiyle üreten yeni bir makine', ['Daha önce hiç satılmamış yeni bir telefon modeli', 'Ürünün yeni bir renkte ve yeni bir ambalajla sunulması', 'Ürünün yeni bir ülkeye satılması'], 'Süreç yeniliği var olan ürünlerin üretim yöntemini değiştirir ve eş ürün eğrilerini orijine yaklaştırır.'),
  ('Belirli bir girdi bileşimiyle ulaşılabilecek en yüksek çıktının üretildiği, yani üretim sınırının üzerinde bulunulan durum nasıl adlandırılır?', 'Teknik etkinlik', ['Tahsis etkinliği', 'Dağılım adaleti', 'Ölçek etkinliği'], 'Teknik etkinlik girdilerin israf edilmemesidir; fiyatlarla ilgilenmez.'),
  ('Aynı girdilerle aynı sektördeki diğer firmalardan daha az çıktı üreten bir fabrikanın bu durumu hangi kavramla ifade edilir?', 'Teknik etkinsizlik', ['Ölçeğe göre artan getiri', 'Tahsis etkinliği', 'Kapsam ekonomisi'], 'Aynı girdilerle daha çok üretmek mümkünse firma üretim sınırının içindedir; bu teknik etkinsizliktir.'),
  ('Neoklasik firma kuramında firmanın temel amacı olarak kabul edilen ve öteki modellerin karşılaştırma noktası olan hedef hangisidir?', 'Kâr maksimizasyonu', ['Pazar payı maksimizasyonu', 'Çalışan memnuniyeti', 'Maliyet maksimizasyonu'], 'Standart kuramda firma kârını en çoklaştırır; maliyet minimizasyonu bu amacın bir ön adımıdır.'),
  ('Talebin Qd = 120 − 4P, arzın Qs = 2P olduğu bir piyasada denge fiyatı ve miktarı hangisidir?', 'P = 20, Q = 40', ['P = 30, Q = 60', 'P = 40, Q = 80', 'P = 15, Q = 60'], '120 − 4P = 2P ⇒ P = 20; Q = 2 × 20 = 40.'),
  ('Aynı piyasada (Qd = 120 − 4P, Qs = 2P) her fiyatta talep 30 birim artarsa yeni denge miktarı kaç olur?', '50', ['40', '70', '45,5'], 'Yeni talep 150 − 4P\'dir: 150 − 4P = 2P ⇒ P = 25, Q = 50.'),
  ('Çiftçilerin bu yılki ekim kararını geçen yılın fiyatına göre verdiği tarım piyasalarında fiyat ve miktarın dalgalanmasını açıklayan model hangisidir?', 'Örümcek ağı (cobweb) modeli', ['Edgeworth kutusu ve sözleşme eğrisi', 'IS-LM modeli', 'Harrod-Domar modeli'], 'Arz bir dönem gecikmeli tepki verdiği için yüksek fiyat ertesi yıl fazla üretime ve düşük fiyata, bu da sonraki yıl az üretime yol açar.'),
  ('Arz eğrisi Qs = 2P olan bir piyasada fiyat 20 TL ise üretici rantı kaç TL\'dir?', '400', ['800', '200', '1.600'], 'Arz eğrisi orijinden çıkar; üretici rantı fiyatın altında kalan üçgendir: ½ × 20 × 40 = 400 TL.'),
  ('Bir sektörde her birinin arzı q = P − 2 olan 100 özdeş firma vardır (P > 2 için). Piyasa arzı hangi fonksiyonla gösterilir?', 'Q = 100P − 200', ['Q = P − 200', 'Q = 100P − 2', 'Q = (P − 2) / 100'], 'Piyasa arzı bireysel arzların yatay toplamıdır: 100 × (P − 2) = 100P − 200.'),
  ('Alfred Marshall\'ın fiyat analizinde arzın hiç değiştirilemediği, örneğin balık pazarında o günkü avın sabit olduğu en kısa döneme ne ad verilir?', 'Piyasa dönemi', ['Kısa dönem', 'Uzun dönem', 'Seküler (çok uzun) dönem'], 'Marshall\'ın piyasa (anlık) döneminde arz dikeydir ve fiyatı tümüyle talep belirler.'),
  ('İki tüketicili ve iki mallı bir mübadele ekonomisinde Pareto etkin dağılımların tamamını gösteren eğriye ne ad verilir?', 'Sözleşme eğrisi', ['Fiyat-tüketim eğrisi', 'Üretim imkânları eğrisi', 'Engel eğrisi'], 'Edgeworth kutusunda iki kişinin kayıtsızlık eğrilerinin teğet olduğu noktalar sözleşme eğrisini oluşturur.'),
  ('Rekabetçi piyasa dengesinin Pareto etkin olduğunu söyleyen önerme hangisidir?', 'Refah iktisadının birinci temel teoremi', ['Refah iktisadının ikinci temel teoremi', 'Arrow\'un imkânsızlık teoremi', 'Coase teoremi'], 'Birinci teorem, dışsallık ve piyasa gücü yokken tam rekabet dengesinin Pareto etkin olduğunu söyler.'),
  ('Bütün piyasaların aynı anda dengede olduğu bir sistemi ilk kez matematiksel olarak tanımlayan ve \'genel denge\' kuramının kurucusu sayılan iktisatçı kimdir?', 'Léon Walras', ['Alfred Marshall', 'Antoine Augustin Cournot', 'Vilfredo Pareto'], 'Walras 1874\'te yayımlanan \'Éléments d\'économie politique pure\' eserinde bütün piyasaların birbirine bağlı dengesini denklem sistemiyle gösterdi.'),
  ('Bir firmanın hasılatı 500 TL, değişken maliyeti 300 TL ve sabit maliyeti 120 TL\'dir. Bu firmanın üretici rantı ve kârı sırasıyla kaçtır?', '200 TL ve 80 TL', ['80 TL ve 200 TL', '200 TL ve 200 TL', '500 TL ve 80 TL'], 'Üretici rantı hasılattan değişken maliyetin çıkarılmasıyla (200 TL), kâr ise ayrıca sabit maliyetin de çıkarılmasıyla (80 TL) bulunur.'),
  ('Ters talep fonksiyonu P = 80 − 2Q olan bir tüketici 10. birim için en fazla kaç TL ödemeye razıdır?', '60', ['70', '40', '78'], 'Ters talep fonksiyonu her birim için marjinal ödeme isteğini verir: 80 − 2 × 10 = 60 TL.'),
  ('Riske karşı nötr bir kişi için kesinlik eşdeğeri ile beklenen değer arasındaki ilişki nedir?', 'Birbirine eşittir.', ['Kesinlik eşdeğeri daha küçüktür.', 'Kesinlik eşdeğeri daha büyüktür.', 'Kesinlik eşdeğeri her zaman sıfırdır.'], 'Doğrusal faydada beklenen fayda beklenen değerin faydasına eşittir; bu yüzden risk primi sıfırdır.'),
  ('Bir kişinin faydası yalnız kendi tüketimine değil, bir yakınının tüketimine de pozitif biçimde bağlıysa bu tercihler nasıl adlandırılır?', 'Özgecil (altruistik) tercihler', ['Leksikografik tercihler', 'Homotetik (orantılı) tercihler', 'Kuasi-lineer tercihler'], 'Özgecil tercihlerde başkasının refahı kişinin fayda fonksiyonuna pozitif bir değişken olarak girer.'),
  ('Bir fabrikada boş üretim kapasitesi ve stoklar bol ise ürünün arz esnekliği için ne beklenir?', 'Yüksek olur; üretim hızla artırılabilir.', ['Sıfır olur; üretim artırılamaz.', 'Negatif olur.', 'Talep esnekliğine eşit olur ve işaret değiştirir.'], 'Atıl kapasite ve stok, firmaların fiyat artışına üretimi hızla artırarak yanıt vermesini sağlar.'),
  ('Talebin fiyat esnekliği −1,5 olan bir malın fiyatı %4 artarsa talep edilen miktar yaklaşık ne kadar değişir?', '%6 azalır.', ['%2,7 azalır.', '%6 artar.', '%1,5 azalır.'], 'Miktardaki yüzde değişim ≈ esneklik × fiyattaki yüzde değişim = −1,5 × 4 = −%6.'),
  ('Bir belediye toplu taşıma bilet fiyatını %20 artırdıktan sonra bilet gelirinin %8 arttığını görüyor. Bu aralıkta talebin fiyat esnekliği için en olası sonuç hangisidir?', 'Mutlak değerce 1\'den küçüktür.', ['Mutlak değerce 1\'den büyüktür.', 'Tam olarak 1\'dir.', 'Pozitiftir; mal bir Giffen malıdır.'], 'Fiyat artarken harcama da artıyorsa miktar fiyattan daha az oranda düşmüştür; talep inelastiktir.'),
  ('Bir malın gelir esnekliği 0,4 ise ve hane gelirleri bir yılda %10 artarsa (fiyatlar sabitken) bu malın talebi yaklaşık ne kadar artar?', '%4', ['%10', '%25', '%0,4'], 'Talep değişimi ≈ 0,4 × %10 = %4. Gelir esnekliği 0 ile 1 arasında olduğundan mal zorunlu maldır.'),
  ('Bir restoranda masa sayısı kısa dönemde sabitken garson sayısı artırılıyor. Bu durumda hangisi sabit, hangisi değişken girdidir?', 'Masalar sabit, garsonlar değişken girdidir.', ['Garsonlar sabit, masalar değişken girdidir.', 'İkisi de sabit girdidir; kısa dönemde hiçbir şey değişmez.', 'İkisi de değişken girdidir.'], 'Kısa dönemde masa sayısı gibi kapasite unsurları değiştirilemez; garson sayısı ise kolayca ayarlanabilir.'),
  ('Bir işçi saatte 12 parça üretirken yeni bir yazılım sayesinde aynı sürede 15 parça üretmeye başlıyor. Emek verimliliği yüzde kaç artmıştır?', '25', ['20', '3', '15,0'], '(15 − 12) / 12 = 0,25, yani %25.'),
  ('Gelir vergisinden önce saat ücreti 40 TL olan birine %25 oranında gelir vergisi uygulanırsa emek-boş zaman bütçe doğrusunun eğimi (mutlak değer) kaça iner?', '30', ['40', '10', '32,5'], 'Vergi sonrası net ücret 40 × 0,75 = 30 TL\'dir; bütçe doğrusu bu eğimle yatıklaşır.'),
  ('İki dönemli modelde gelecek dönem tüketimini bugünkü tüketime göre daha az önemseyen, yani sabırsız bir tüketicinin zaman tercih oranı için ne söylenir?', 'Pozitiftir; gelecek fayda iskonto edilir.', ['Negatiftir.', 'Sıfırdır.', 'Faiz oranına her zaman ve her kişide tam olarak eşittir.'], 'Pozitif zaman tercih oranı, aynı tüketimin gelecekte bugünkünden daha az fayda sağladığı anlamına gelir.'),
  ('Bir kişi %20 olasılıkla 500 TL, %30 olasılıkla 100 TL ve %50 olasılıkla hiçbir şey kazanmayacağı bir oyunu oynayabilir. Oyunun beklenen değeri kaç TL\'dir?', '130', ['200', '300', '100'], '0,2 × 500 + 0,3 × 100 + 0,5 × 0 = 100 + 30 = 130 TL.'),
  ('Bir tüketici ekmek ve peynir arasında seçim yaparken peynirin fiyatı düşünce hem peynir hem de ekmek tüketimini artırıyor. Ekmek ile peynir arasındaki ilişki nasıl adlandırılır?', 'Brüt tamamlayıcı', ['Brüt ikame', 'Bağımsız mal', 'Düşük mal'], 'Bir malın fiyatı düşünce diğerinin talebi artıyorsa (çapraz esneklik negatif) mallar brüt tamamlayıcıdır.'),
  ('Q = K·L üretim fonksiyonunda 4 birim sermaye ve 4 birim emekle elde edilen çıktı düzeyini 8 birim emekle üretmek için kaç birim sermaye gerekir?', '2', ['4', '8', '0,5'], 'Çıktı 4 × 4 = 16\'dır; aynı eş ürün eğrisinde L = 8 için K = 16 / 8 = 2 olur.'),
  ('Bir firma bütün girdilerini iki katına çıkardığında çıktısının %150 arttığını görüyor. Bu firma için ne söylenebilir?', 'Ölçeğe göre artan getiri vardır.', ['Ölçeğe göre azalan getiri vardır.', 'Ölçeğe göre sabit getiri vardır.', 'Azalan marjinal verim yoktur.'], 'Çıktı 2,5 katına çıkmıştır; girdi artışından (2 kat) fazla olduğu için ölçeğe göre artan getiri söz konusudur.'),
  ('Sermaye verimliliği (sermayenin ortalama ürünü) nasıl hesaplanır?', 'Toplam çıktının kullanılan sermaye miktarına bölünmesiyle', ['Toplam çıktının işçi sayısına bölünmesiyle', 'Sermayenin kirasının ve amortismanın toplam çıktıya bölünmesiyle', 'Toplam maliyetin sermayeye bölünmesiyle'], 'APK = Q / K; bir birim sermayenin ortalama olarak ne kadar çıktı ürettiğini gösterir.'),
  ('Rekabetçi bir firmada ücret düşerse, ürün fiyatı ve sermaye sabitken kısa dönemde kârını en çoklaştıran firma ne yapar?', 'Marjinal ürün değeri yeni ücrete eşitlenene kadar daha çok işçi çalıştırır.', ['Çalıştırdığı işçi sayısını azaltır.', 'İşçi sayısını değiştirmez, yalnızca sermayeyi artırarak üretimi büyütür.', 'Üretimi durdurur.'], 'Ücret düştüğünde önceki son işçinin marjinal ürün değeri ücretin üzerinde kalır; azalan marjinal ürün nedeniyle firma yeni eşitliğe kadar istihdamı artırır.'),
  ('Aşağıdakilerden hangisi tüketici kuramında \'kötü mal\' (bad) örneğidir?', 'Evin yakınındaki çöp yığını', ['Bir kutu çikolata', 'Bir sinema bileti ve yanında patlamış mısır', 'Bir kilogram elma'], 'Kötü mal, miktarı arttıkça faydayı azaltan şeydir; tüketiciler ondan kurtulmak için ödeme yapmaya bile razı olabilir.'),
  ('Kayıtsızlık eğrisinin herhangi bir noktadaki eğimi tüketici açısından neyi gösterir?', 'Tüketicinin bir maldan bir birim daha almak için diğerinden ne kadar vazgeçmeye razı olduğunu', ['İki malın piyasa fiyatları arasındaki oranı ve göreli pahalılığı', 'Tüketicinin gelirini', 'Malların üretim maliyetini'], 'Bu eğim marjinal ikame oranıdır ve tüketicinin öznel takas oranını gösterir; bütçe doğrusunun eğimi ise piyasanın takas oranıdır.'),
  ('Bir tüketicinin kayıtsızlık haritasında orijinden daha uzaktaki bir eğri neyi temsil eder?', 'Daha yüksek bir fayda düzeyini', ['Daha düşük bir fayda düzeyini', 'Daha düşük fiyatları ve daha geniş bir bütçeyi', 'Aynı fayda düzeyini'], 'Malların ikisi de \'iyi\' olduğunda orijinden uzaklaşmak iki maldan da daha fazlası demektir; bu da daha yüksek fayda anlamına gelir.'),
  ('Riskten kaçınan bir kişiye kesin 100 TL ile %50 olasılıkla 0 TL, %50 olasılıkla 200 TL veren bir kumar arasında seçim sunuluyor. Bu kişi hangisini seçer?', 'Kesin 100 TL\'yi', ['Kumarı', 'İkisine kayıtsız kalır.', 'Kumara para ödeyerek katılmayı'], 'İki seçeneğin beklenen değeri 100 TL\'dir; riskten kaçınan kişi aynı beklenen değerde kesin sonucu tercih eder.'),
  ('Riske karşı nötr bir kişi seçenekleri hangi ölçüte göre sıralar?', 'Yalnızca beklenen değerlerine göre', ['Yalnızca en kötü sonuca göre', 'Yalnızca en iyi sonuca göre', 'Sonuçların değişkenliğine ve en kötü olasılığa göre'], 'Riske nötr kişinin fayda fonksiyonu doğrusaldır; riskin kendisi onun için ne iyi ne kötüdür.'),
  ('Ev sigortası yaptırmak için beklenen kaybın üzerinde prim ödemeye razı olan bir kişinin risk tutumu nedir?', 'Riskten kaçınan', ['Riski seven', 'Riske karşı nötr', 'Belirsizliği seven'], 'Beklenen kaybın üzerinde ödeme yapmak, riski üstlenmemek için bir bedele katlanmaktır; bu riskten kaçınmanın göstergesidir.'),
  ('Bir taksi şirketinde her araç için tam olarak bir şoför gerekiyorsa, araç ve şoför girdileri arasındaki üretim ilişkisi en iyi hangi fonksiyonla gösterilir?', 'Sabit oranlı (Leontief) üretim fonksiyonu', ['Doğrusal (tam ikame) üretim fonksiyonu', 'Ölçeğe göre artan getirili Cobb-Douglas fonksiyonu', 'Üstel büyüme fonksiyonu'], 'Şoförsüz araç ya da araçsız şoför ek hizmet üretmez; girdiler sabit oranda kullanılır.'),
  ('Bir pastanede un, şeker, fırın, elektrik ve pastacının emeği kullanılarak pasta yapılıyor. Bu süreçte pasta neyi temsil eder?', 'Çıktıyı', ['Sabit girdiyi', 'Değişken girdiyi', 'Üretim teknolojisini'], 'Üretim fonksiyonu girdileri (un, emek, fırın) çıktıya (pasta) dönüştüren teknik ilişkidir.'),
  ('Yeni bir teknoloji aynı girdilerle daha çok çıktı üretmeyi sağlıyorsa toplam ürün eğrisi nasıl etkilenir?', 'Yukarı doğru kayar.', ['Aşağı doğru kayar.', 'Değişmez.', 'Yatay hâle gelir ve artık yükselmez.'], 'Teknolojik ilerleme her girdi düzeyinde elde edilebilecek azami çıktıyı artırır; üretim fonksiyonu yukarı kayar.'),
  ('Bir tüketici bir sepetteki her iki maldan da daha fazlasını içeren ikinci bir sepeti birincisine tercih ediyor. Bu tercih hangi varsayımla uyumludur?', 'Monotonluk', ['Dışbükeylik', 'Tamlık', 'Süreklilik'], 'Monotonluk varsayımına göre her maldan daha fazlasını içeren sepet en az eskisi kadar iyidir.'),
  ('Kayıtsızlık eğrisi analizinde \'bütçe doğrusu\' ile \'kayıtsızlık eğrisi\' arasındaki temel fark hangisidir?', 'Bütçe doğrusu neyin alınabileceğini, kayıtsızlık eğrisi neyin istendiğini gösterir.', ['Bütçe doğrusu tüketicinin tercihlerini, kayıtsızlık eğrisi ise piyasa fiyatlarını ve geliri gösterir.', 'İkisi aynı bilgiyi verir.', 'Bütçe doğrusu üreticiye, kayıtsızlık eğrisi devlete aittir.'], 'Bütçe doğrusu gelir ve fiyatlardan, kayıtsızlık eğrisi tercihlerden doğar; denge ikisinin buluştuğu yerde oluşur.'),
  ('Bir öğrenci \'iki ders kitabı yerine bir kitap ve bir sinema bileti olsa daha mutlu olurum\' diyor. Bu öğrencinin tercihleri hangi özelliği yansıtır?', 'Çeşitliliği sevme', ['Leksikografik (sözlük sıralı) tercihler', 'Tam tamamlayıcılık', 'Kötü mal tercihi'], 'Dışbükey tercihlerde tüketici uç sepetler yerine karışık sepetleri tercih eder.'),
  ('Birim başına vergi konan bir piyasada alıcıların ödediği fiyat ile satıcıların eline geçen fiyat arasındaki farka ne ad verilir?', 'Vergi takozu', ['Tüketici rantı', 'Fiyat esnekliği', 'Arz fazlası'], 'Vergi takozu birim vergiye eşittir; alıcı ve satıcı fiyatları arasına giren bu fark işlem miktarını düşürür.'),
  ('Emekliliğe yakın bir kişinin bu yıl 100.000 TL geliri var, gelecek yıl hiç geliri olmayacak. Bu yıl 60.000 TL tüketir ve kalanı %5 faizle biriktirirse gelecek yıl kaç TL tüketebilir?', '42.000', ['40.000', '45.000', '63.000,0'], 'Biriken 40.000 TL faiziyle 40.000 × 1,05 = 42.000 TL olur.'),
  ('Faiz oranının yükselmesi bugünkü tüketimin gelecekteki tüketime göre göreli fiyatını nasıl etkiler?', 'Artırır; bugün tüketmek daha pahalı hâle gelir.', ['Azaltır; bugün tüketmek ucuzlar.', 'Etkilemez.', 'Yalnızca gelecekteki tüketimin fiyatını düşürür, bugünkünü etkilemez.'], 'Bugün harcanan 1 TL, biriktirilseydi yarın 1 + r TL olacaktı; r arttıkça bugünkü tüketimin fırsat maliyeti yükselir.'),
  ('Riskten kaçınan bir kişinin bir piyangonun beklenen değerinin altında bir kesin tutarı kabul etmesinin nedeni nedir?', 'Belirsizliğin kendisi ona fayda kaybı yaşattığı için', ['Beklenen değeri yanlış hesapladığı için', 'Paranın marjinal faydası arttığı için', 'Piyangonun beklenen değeri her zaman negatif olduğu için'], 'İçbükey faydada kayıpların acısı aynı büyüklükteki kazancın hazzından ağır basar; risksiz sonuç için bedel ödenir.'),
  ('Örümcek ağı modelinin temel varsayımlarından biri hangisidir?', 'Üreticilerin bu dönemki arz kararını geçen dönemin fiyatına göre vermesi', ['Üreticilerin geleceği kusursuz biçimde öngörmesi ve fiyatı bugünden bilmesi', 'Talebin bir dönem gecikmeli tepki vermesi', 'Fiyatın devlet tarafından belirlenmesi'], 'Model, gecikmeli arz tepkisi ve uyarlanmayan (naif) beklentiler varsayımına dayanır.'),
  ('Bir tarım ürününün fiyatı bir yıl çok yükselince ertesi yıl birçok çiftçinin bu ürüne geçmesi ve fiyatların çökmesi en iyi hangi kavramla açıklanır?', 'Örümcek ağı dalgalanması', ['Ölçek ekonomisi', 'Bandwagon (çoğunluğa uyma) etkisi', 'Gelir etkisi'], 'Üreticilerin geçen yılın fiyatına göre ekim yapması, arzın aşırı tepki vermesine ve fiyatların dalgalanmasına yol açar.'),
  ('Bir yol ya da internet bağlantısı kullanıcı sayısı arttıkça yavaşlıyorsa bu durum hangi kavramla açıklanır?', 'Negatif ağ dışsallığı', ['Pozitif ağ etkisi ve kritik kütlenin aşılması', 'Ölçek ekonomisi', 'Bandwagon etkisi'], 'Her yeni kullanıcı diğerlerinin hizmet kalitesini düşürür; sıkışıklık negatif bir ağ etkisidir.'),
  ('Bir hanede ücretler arttıkça evde yemek yapmak yerine hazır yemek siparişinin artması Becker\'ın kuramıyla nasıl açıklanır?', 'Zamanın fırsat maliyeti arttığı için zaman yoğun ev üretiminden mal yoğun seçeneklere geçilir.', ['Hazır yemek düşük mal olduğu için talebi artar.', 'Ücret artışı hanenin bütçe kısıtını daralttığı için daha ucuz olan hazır yemek seçilir.', 'Ev yemeği bir Veblen malı olduğu için talebi düşer.'], 'Yüksek ücret, evde geçirilen zamanın maliyetini yükseltir; hane zamandan tasarruf ettiren piyasa mallarına yönelir.'),
  ('Emek-boş zaman modelinde günlük 24 saatin tamamı boş zaman olarak tüketilse bile kişinin elde ettiği gelir hangisidir?', 'Emek dışı gelir', ['Ücret ile 24 saatin çarpımı', 'Sıfırdan küçük bir gelir', 'Rezervasyon ücreti'], 'Hiç çalışmayan kişi yalnızca emek dışı gelirine (kira, transfer vb.) sahiptir; bütçe doğrusunun dikey parçası bu tutardadır.'),
  ('Kısa dönem toplam maliyet eğrisinin dikey ekseni (sıfır üretimde) kestiği nokta neyi gösterir?', 'Toplam sabit maliyeti', ['Toplam değişken maliyeti', 'Marjinal maliyeti', 'Ortalama maliyeti'], 'Hiç üretim yapılmasa da kısa dönemde sabit maliyete katlanılır; toplam maliyet eğrisi bu tutardan başlar.'),
  ('Uzun dönem toplam maliyet eğrisi neden orijinden başlar?', 'Uzun dönemde bütün girdiler değişken olduğu için sıfır üretimin maliyeti sıfırdır.', ['Uzun dönemde girdi fiyatları sıfırdır.', 'Uzun dönemde firma hiç üretim yapmaz.', 'Uzun dönemde sabit maliyetler ortadan kalkmaz, yalnızca iki katına çıkarak yayılır.'], 'Uzun dönemde firma hiçbir girdi kullanmamayı seçebilir; bu yüzden kaçınılamaz sabit maliyet yoktur.'),
  ('Bir atölyede 1., 2. ve 3. işçinin marjinal ürünleri sırasıyla 8, 7 ve 6 birimdir. Üç işçiyle toplam ürün kaç birimdir?', '21', ['6', '7', '18,0'], 'Toplam ürün marjinal ürünlerin toplamıdır: 8 + 7 + 6 = 21 birim.'),
  ('4 işçinin günde toplam 60 birim ürettiği bir atölyede emeğin ortalama ürünü kaçtır?', '15', ['240', '64', '12'], 'APL = Q / L = 60 / 4 = 15 birim.'),
  ('Bir firma bütün girdilerini %10 artırdığında toplam maliyeti %10, çıktısı %15 artıyorsa uzun dönem ortalama maliyeti nasıl değişir?', 'Azalır.', ['Artar.', 'Değişmez.', 'Önce artar sonra azalır.'], 'Maliyet çıktıdan daha yavaş arttığı için birim maliyet düşer; bu ölçek ekonomisidir.'),
  ('Bir firmada çalışan sayısı %10 artırılınca (sermaye sabitken) çıktı %6 artmıştır. Emeğin çıktı esnekliği yaklaşık kaçtır?', '0,6', ['1,67', '6', '0,06'], 'Çıktı esnekliği = %ΔQ / %ΔL = 6 / 10 = 0,6.'),
  ('Bir kişinin bugünkü kahve tüketiminden aldığı faydanın geçmişte ne kadar kahve içtiğine bağlı olması hangi kavramla açıklanır?', 'Alışkanlık oluşumu', ['Gösteriş (Veblen) tüketimi', 'Ölçek ekonomisi', 'Ters seçim'], 'Alışkanlık oluşumunda geçmiş tüketim bugünkü tercihleri etkiler; bu da kısa dönemde talebi fiyata daha az duyarlı yapar.'),
  ('Günde en fazla 1.000 birim üretebilen bir fabrika 800 birim üretiyorsa kapasite kullanım oranı yüzde kaçtır?', '80', ['20', '125', '8'], 'Kapasite kullanım oranı = 800 / 1.000 = %80.'),
  ('Bir telefonun fiyatı 30.000 TL, bir çalışanın saat ücreti 150 TL\'dir. Bu çalışanın telefonu alabilmesi için kaç saat çalışması gerekir?', '200', ['150', '300', '45,0'], '30.000 / 150 = 200 saat. Bir malın fiyatını çalışma saati cinsinden ifade etmek onun reel maliyetini gösterir.'),
  ('Bir firmanın yeni bir makineye yatırım yapması sonucu aynı çıktıyı daha az işçiyle üretmesi, emek-boş zaman açısından değil üretim kuramı açısından nasıl adlandırılır?', 'Emeğin yerine sermayenin ikame edilmesi', ['Emeğin marjinal ürününün negatif olması ve işten çıkarma', 'Ölçeğe göre azalan getiri', 'Tüketici rantının artması'], 'Firma eş ürün eğrisi üzerinde sermaye yoğun bir noktaya kayarak aynı çıktıyı farklı bir girdi bileşimiyle üretir.'),
  ('İki tüketicinin talepleri Q₁ = 10 − P ve Q₂ = 20 − 2P\'dir. Fiyat 4 TL iken piyasa talebi kaç birimdir?', '18', ['6', '12', '30,0'], 'Bireysel talepler yatay toplanır: 6 + 12 = 18 birim.'),
];
